import json, pathlib, statistics, gzip
from PIL import Image, ImageDraw, ImageFont

root=pathlib.Path('docs/mission-15-evidence/snow-sky')
load=lambda name:json.loads((root/name).read_text())
font='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
f=ImageFont.truetype(font,18)
small=ImageFont.truetype(font,14)
scenes=['rue','pont','foret','falaise','toitures','persistants']
sheet=Image.new('RGB',(1440,len(scenes)*350+55),'#132825');d=ImageDraw.Draw(sheet)
d.text((15,16),'15B · prises réelles · janvier · mêmes caméras et lumière · dépôt de diagnostic',font=f,fill='white')
for row,scene in enumerate(scenes):
 for col,(level,label) in enumerate([('bare','Sans neige'),('light','Dépôt 0,18'),('covered','Dépôt 0,85')]):
  im=Image.open(root/f'{scene}-{level}-balanced.jpg');im.thumbnail((480,320));y=55+row*350;sheet.paste(im,(col*480,y));d.text((col*480+10,y+324),scene+' · '+label,font=small,fill='white')
sheet.save(root/'comparison.jpg',quality=88)

captures=load('captures.json')['rows']
cards=''.join(f'<figure><a href="{r["file"]}"><img loading="lazy" src="{r["file"]}" alt="{r["id"]} · {r["level"]} · {r["profile"]}"></a><figcaption>{r["id"]} · {r["level"]} · {r["profile"]}</figcaption></figure>' for r in captures)
clouds=''.join(f'<figure><a href="{phase}-cloud-{s}s.jpg"><img loading="lazy" src="{phase}-cloud-{s}s.jpg" alt="Nuages {phase}, {s} secondes"></a><figcaption>{phase} · {s} secondes réelles</figcaption></figure>' for phase in ['before','after'] for s in [0,60,120,180,240])
motion=''.join(f'<figure><a href="{mode}-{s}s.jpg"><img loading="lazy" src="{mode}-{s}s.jpg" alt="{mode}, {s} secondes"></a><figcaption>{mode} · {s} secondes réelles</figcaption></figure>' for mode,times in [('snow-walk',[0,30,60,90,110,120]),('melt',[0,60,120,180,240,300]),('light',[0,15,30]),('heavy',[0,15,30])] for s in times)
videos=''.join(f'<figure><video controls preload="metadata" poster="{poster}" src="{name}.webm"></video><figcaption>{label} · <a href="{name}.json">mesures</a></figcaption></figure>' for name,poster,label in [('snow-walk','snow-walk-60s.jpg','Début naturel, puis marche · 120 s · audio réel'),('melt','melt-120s.jpg','Fonte native · 300 s · dépôt initial diagnostique 0,24'),('light','light-15s.jpg','Flocons faibles · 30 s · intensité 0,15'),('heavy','heavy-15s.jpg','Flocons forts · 30 s · intensité 1')])
altcards=''.join(f'<figure><a href="alternative-{id}-{v}.jpg"><img loading="lazy" src="alternative-{id}-{v}.jpg" alt="Variante {id} · {v}"></a><figcaption>{v} · {id}</figcaption></figure>' for v in ['rue','foret','vallee'] for id in ['retained','coarse','unprotected'])
perf=load('performance-summary.json')['summary']
table='<table><caption>SwiftShader logiciel · rendu synchronisé 960 × 640 · médiane / P95 / pic en ms</caption><thead><tr><th>Profil · scène</th><th>Variante</th><th>Médiane</th><th>P95</th><th>Pic</th><th>Écart / 15A</th></tr></thead><tbody>'+''.join(f'<tr><td>{r["profile"]} · {r["id"]}</td><td>{r["variant"]}</td><td>{r["medianMs"]:.1f}</td><td>{r["p95Ms"]:.1f}</td><td>{r["peakMs"]:.1f}</td><td>{r["deltaPercent"]:+.1f} %</td></tr>' for r in perf)+'</tbody></table>'
html=f'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Endless Earth · 15B · Neige et ciel vivant</title><style>body{{margin:0;background:#112b27;color:#f4f1e7;font:16px/1.6 system-ui}}main{{max-width:1350px;margin:auto;padding:24px}}h1,h2{{font-family:Georgia,serif}}a{{color:#c5e5dc}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:16px}}figure{{margin:0;background:#203d37;padding:10px}}img,video{{width:100%;height:auto;display:block}}figcaption{{padding-top:6px}}table{{border-collapse:collapse;width:100%}}td,th{{border-bottom:1px solid #58736b;text-align:left;padding:7px}}caption{{text-align:left}}.scroll{{overflow:auto}}p{{max-width:90ch}}</style><main>
<h1>15B · Neige et ciel vivant</h1><p>Proposition pour validation artistique. 15A accepté par « go ». Arrêt avant 15C. Aucun déploiement ni fusion. <a href="../../mission-15.md">Rapport complet</a> · <a href="../index.html">Historique 15A</a>.</p>
<p>Images et vidéos issues du vrai moteur. Les poses d’inspection sont séparées ; seule la vidéo de marche suit une promenade continue. Le niveau 0,18 / 0,85 est un diagnostic reproductible. Les films tournent à vitesse normale sur SwiftShader logiciel, sans prétendre mesurer un GPU physique.</p>
<h2>Le paysage transformé</h2><a href="comparison.jpg"><img src="comparison.jpg" alt="Sans neige, dépôt faible et fort dans six scènes"></a>
<h2>Flocons, début d’accumulation, marche et fonte</h2><div class="grid">{videos}</div><div class="grid">{motion}</div>
<h2>Nuages : observation native de quatre minutes</h2><p>Vent d’advection conservé. Formes lentement renouvelées ; couche basse à 230 m, cohérente avec le champ d’ombres, couche haute à 540 m. Les vidéos retiennent les 120 premières secondes, sans accélération ; les captures couvrent les 240 secondes.</p><div class="grid"><figure><video controls preload="metadata" poster="before-cloud-0s.jpg" src="before-clouds.webm"></video><figcaption>15A · <a href="before-cloud-observation.json">observation</a></figcaption></figure><figure><video controls preload="metadata" poster="after-cloud-0s.jpg" src="after-clouds.webm"></video><figcaption>15B · <a href="after-cloud-observation.json">observation</a></figcaption></figure></div><div class="grid">{clouds}</div>
<h2>Contrôles du build compilé</h2><p>Sans injection de sources ni masquage des commandes. <a href="compiled.json">État et identité du build</a>.</p><div class="grid"><figure><img loading="lazy" src="desktop-controls.jpg" alt="Menu Neigeux dans le build compilé"><figcaption>Menu météo ordinaire · Neigeux</figcaption></figure><figure><img loading="lazy" src="mobile-controls.jpg" alt="Jeu compilé avec commandes mobiles"><figcaption>Mobile · commandes existantes</figcaption></figure></div><h2>Toutes les prises et les trois profils</h2><p>Le pont, son dessous et les vues élevées sont des points d’inspection diagnostiques ; ils ne constituent pas la preuve d’un itinéraire accessible depuis la rue. L’eau reste courante, sans modèle de glace. Les façades verticales et les dessous d’ouvrage conservent leur matériau.</p><div class="grid">{cards}</div>
<h2>Alternatives mesurées</h2><p>Essai séparé : retained = livré, coarse = un grain, unprotected = un grain et protection des abris retirée. Cette dernière enfreint le critère d’abri. Les variantes sont injectées seulement pour ce banc. <a href="alternatives.json">Mesures et méthode</a>.</p><div class="grid">{altcards}</div><h2>Coût graphique</h2><div class="scroll">{table}</div><p><a href="performance-summary.json">Mesures, allocations, chargement et streaming</a> · <a href="performance.json.gz">Trace</a> · <a href="runtime.json">Navigation, audio et erreurs de données</a> · <a href="audit.json">Audit de sources et droits</a> · <a href="validation.json">Validation finale</a>.</p>
<p>Limites : fine apparence colorée, sans épaisseur physique ni congères ; abri approximé à 1,95 m par texel, sans collision feuille par feuille ; aucun nouvel enregistrement de pas sur neige. Le calendrier garde les feuillus hivernaux dégarnis et les persistants feuillés. L’appréciation du naturel reste humaine.</p></main></html>'''
(root/'index.html').write_text(html)
print('Wrote 15B real evidence gallery and contact sheet')
